Lemma land_mod_low : forall z k b, 0 <= k -> 0 <= b < 2^k -> Z.land (z mod 2^k) b = Z.land z b.
Proof.
  intros z k b Hk Hb. rewrite <- (Z.land_ones z k) by lia.
  rewrite <- Z.land_assoc. f_equal. rewrite Z.land_comm. rewrite Z.land_ones by lia. apply Z.mod_small. lia.
Qed.
