Lemma swrap32_mod : forall u, (bv_swrap 32 u) mod 2^32 = u mod 2^32.
Proof.
  intros u. unfold bv_swrap, bv_wrap. change (bv_modulus 32) with (2^32). change (bv_half_modulus 32) with (2^31).
  rewrite Zminus_mod_idemp_l. f_equal. lia.
Qed.
