Lemma land_sx32_low : forall (w : word) b, 0 <= b < 2^32 -> Z.land (bv_unsigned (sx32 w)) b = Z.land (bv_unsigned w) b.
Proof.
  intros w b Hb. unfold sx32. rewrite Z_to_bv_unsigned. change (bv_wrap 64 ?x) with (x mod 2^64).
  rewrite land_mod_low by lia. rewrite <- (land_mod_low (bv_swrap _ _) 32 b) by lia. rewrite swrap32_mod. apply land_mod_low; lia.
Qed.
