Lemma zbv_wrap : forall z, Z_to_bv 64 z = Z_to_bv 64 (z - 2^64).
Proof.
  intros z. apply bv_eq. rewrite !Z_to_bv_unsigned. change (bv_wrap 64 ?a = bv_wrap 64 ?b) with (a mod 2^64 = b mod 2^64).
  rewrite <- (Z.mod_add (z - 2^64) 1 (2^64)) by lia. f_equal. lia.
Qed.
