        eapply aevtM_cut.
        { eapply SPK with (LB := Lx ++ LB) (PP := PP) (CUR := CRT + 448) (P := q) (END := EOC) (BUF := BUF) (bs := bs) (lo := lo) (h := hc);
            rewrite ?USP, ?HTc; try eassumption; try reflexivity; try (is_arith_goal; plia); try (clear - ALC' ALP' SP16 SPR; Z.div_mod_to_equations; is_arith_goal; lia).
          all: try (unfold X509_POLICIES_STACK, X509_AKID_STACK; is_arith_goal; plia).
          all: try (intros a Ha; left; is_arith_goal; lia).
          all: eapply client_range_block; [apply in_or_app; right; exact BIN| lia| lia]. }
        intros ms' mo'x PO.
        destruct PO as (u0 & u1 & u2 & ua0 & ua1 & ua2 & ua3 & ua4 & ua5 & ua6 & ua7 & u3 & u4 & u5 & u6 & m2 & mo2 & h2 & r & p2 & ct & cp & cl & cq & cn & nodes
                        & E0 & MI2 & ST2 & MF2 & HT2 & -> & Hr & PPc2 & Hp2 & XS2 & RNG & Hcn & CH & ND & APART & HH2 & HPX2).
        injection E0; clear E0; intros Emo Ems. subst ms' mo'x. rewrite ?USP in ST2. rewrite ?USP in HPX2. fix_ret 0x27030. clear SPK.
        assert (XD : forall A0 kk, (A0 + kk <= PP \/ PP + 8 <= A0) -> (A0 + kk <= CRT + 448 \/ CRT + 480 <= A0) -> disjoint_from [(PP, PP + 8); (CRT + 448, CRT + 448 + 32)] A0 kk)
          by (intros A0 kk Y1 Y2; cbn; lia).
        clear PPc XS. trX HPX2 XD. rename PPc2 into PPc. rename XS2 into XS.
        assert (HPX1 : heap_presx usegs L LB (bv_unsigned sp) X0 m m2).
        { eapply heap_presx_trans; [exact HPXc|]. eapply HPXdown; [exact HHc| exact HPX2|]. intros a Ha Ho. cbn [outside] in Ho |- *. lia. }
        pose proof (heap_presx_bytes_at usegs L _ _ _ _ _ _ _ HPX2 BYc ltac:(eapply client_range_block; [apply in_or_app; right; exact BIN| lia| lia]) ltac:(cbn; lia)) as BY2.
        assert (SO2 : statics_ok usegs L m2).
