        set (X2 := setsan X ct cp cl cq cn nodes (Z.lor (x_seen X) 32)).
        assert (LS2 : LS (map (fun a => (a, 32)) (rev nodes) ++ Lx) m2 mo2 h2 X2 etl crit (Z_to_bv 64 6) opd olen op ln p2).
        { split; [| split; [unfold FRAME, CONSTS, LOCALS; cbn [app]; exact FR| split; [| split; [exact PPc| lia]]]].
          - split; [rewrite <- app_assoc; exact HH2|]. split; [congruence|]. split; [eapply mo_frame_trans; eassumption|]. split; [exact HPX1|].
