              split; [intros Hb; apply XZ2; rewrite Z.land_lor_distr_l in Hb; exact (proj1 (proj1 (Z.lor_eq_0_iff _ _) Hb))|].
              split; [intros Hb; apply XZ3; rewrite Z.land_lor_distr_l in Hb; exact (proj1 (proj1 (Z.lor_eq_0_iff _ _) Hb))|].
              split; [intros Hb; apply XZ4; rewrite Z.land_lor_distr_l in Hb; exact (proj1 (proj1 (Z.lor_eq_0_iff _ _) Hb))|].
              exact HSUB.
            + subst X2. unfold xblocks, setsan. cbn -[app map rev SSEQ].
