        eapply aevtM_cut.
        { eapply SPK with (LB := Lx ++ LB) (PP := PP) (AK := CRT + 504) (P := q) (END := EOC) (BUF := BUF) (bs := bs) (lo := lo) (h := hc);
            rewrite ?USP, ?HTc; try eassumption; try reflexivity; try (is_arith_goal; plia); try (clear - ALC' ALP' SP16 SPR; Z.div_mod_to_equations; is_arith_goal; lia).
          all: try (unfold X509_POLICIES_STACK, X509_AKID_STACK; is_arith_goal; plia).
          all: try (intros a Ha; left; is_arith_goal; lia).
          all: eapply client_range_block; [apply in_or_app; right; exact BIN| lia| lia]. }
        intros ms' mo'x PO.
        destruct PO as (u0 & u1 & u2 & ua0 & ua1 & ua2 & ua3 & ua4 & ua5 & ua6 & ua7 & u3 & u4 & u5 & u6 & m2 & mo2 & h2 & r & p2
                        & k1' & k2' & k3' & k4' & ct & cp & cl & cq & cn & r1' & r2' & r3' & r4' & nodes
                        & E0 & MI2 & ST2 & MF2 & HT2 & -> & Hr & PPc2 & Hp2 & XA2 & RNG & Hcn & CH & ND & APART & HH2 & HPX2).
        injection E0; clear E0; intros Emo Ems. subst ms' mo'x. rewrite ?USP in ST2. rewrite ?USP in HPX2. fix_ret 0x26f48. clear SPK.
        assert (XD : forall A0 kk, (A0 + kk <= PP \/ PP + 8 <= A0) -> (A0 + kk <= CRT + 504 \/ CRT + 584 <= A0) -> disjoint_from [(PP, PP + 8); (CRT + 504, CRT + 504 + 80)] A0 kk)
          by (intros A0 kk Y1 Y2; cbn; lia).
        clear PPc XA. trX HPX2 XD. rename PPc2 into PPc. rename XA2 into XA.
        assert (HPX1 : heap_presx usegs L LB (bv_unsigned sp) X0 m m2).
        { eapply heap_presx_trans; [exact HPXc|]. eapply HPXdown; [exact HHc| exact HPX2|]. intros a Ha Ho. cbn [outside] in Ho |- *. lia. }
        pose proof (heap_presx_bytes_at usegs L _ _ _ _ _ _ _ HPX2 BYc ltac:(eapply client_range_block; [apply in_or_app; right; exact BIN| lia| lia]) ltac:(cbn; lia)) as BY2.
        assert (SO2 : statics_ok usegs L m2).
        { eapply statics_ok_heap_presx; [exact SOc| exact HPX2| exact SW|]. intros a Ha _. cbn [outside]. lia. }
        chains_across HPX2 HHc XO.
        set (X2 := setakid X k1' k2' k3' k4' ct cp cl cq cn nodes r1' r2' r3' r4' (Z.lor (x_seen X) 1)).
        assert (LS2 : LS (map (fun a => (a, 32)) (rev nodes) ++ Lx) m2 mo2 h2 X2 etl crit (Z_to_bv 64 6) opd olen op ln p2).
        { split; [| split; [unfold FRAME, CONSTS, LOCALS; cbn [app]; exact FR| split; [| split; [exact PPc| lia]]]].
          - split; [rewrite <- app_assoc; exact HH2|]. split; [congruence|]. split; [eapply mo_frame_trans; eassumption|]. split; [exact HPX1|].
            split; [exact BY2|]. split; [exact MI2|]. split; [exact SO2| exact ST2].
          - split; [subst X2; unfold setakid; xc_close|]. split.
            + subst X2. unfold xown, setakid. cbn -[Z.land Z.lor bv_unsigned app map rev].
              split; [split; [exact XE1| eapply seq_chain_sub; [exact XQ1| intros b Hb; rewrite <- app_assoc; apply in_or_app; right; exact Hb]] |].
              split; [split; [exact Hcn| rewrite <- app_assoc; exact CH] |].
              split; [split; [exact XE3| eapply seq_chain_sub; [exact XQ3| intros b Hb; rewrite <- app_assoc; apply in_or_app; right; exact Hb]] |].
              split; [split; [exact XE4| eapply seq_chain_sub; [exact XQ4| intros b Hb; rewrite <- app_assoc; apply in_or_app; right; exact Hb]] |].
              split; [intros Hb; apply XZ1; rewrite Z.land_lor_distr_l in Hb; exact (proj1 (proj1 (Z.lor_eq_0_iff _ _) Hb))|].
              split; [intros Hb; exfalso; rewrite Z.land_lor_distr_l in Hb; pose proof (proj2 (proj1 (Z.lor_eq_0_iff _ _) Hb)) as Hb2; vm_compute in Hb2; discriminate Hb2|].
              split; [intros Hb; apply XZ3; rewrite Z.land_lor_distr_l in Hb; exact (proj1 (proj1 (Z.lor_eq_0_iff _ _) Hb))|].
              split; [intros Hb; apply XZ4; rewrite Z.land_lor_distr_l in Hb; exact (proj1 (proj1 (Z.lor_eq_0_iff _ _) Hb))|].
              exact HSUB.
            + subst X2. unfold xblocks, setakid. cbn -[app map rev SSEQ].
              unfold xblocks in PERM. rewrite Znodes in PERM. cbn [SSEQ map app] in PERM.
              eapply Permutation_trans; [apply Permutation_app; [apply SSEQ_rev| exact PERM] |]. rewrite app_nil_r.
              rewrite (app_assoc (SSEQ (x_snodes X)) (SSEQ (x_pnodes X)) (SSEQ nodes)), (app_assoc (SSEQ (x_enodes X)) (SSEQ (x_snodes X) ++ SSEQ (x_pnodes X)) (SSEQ nodes)).
              apply Permutation_app_comm. }
