        - kz KR. zstep. flat constr:(LS2) 5%nat. flclear LS2. intros Bn FRn XOKn PPcn Hqn. eapply L_818; [| lia]. split; [exact Bn| split; [exact FRn| split; [exact XOKn| split; [exact PPcn| lia]]]].
      Qed.
